operacion.codigo_juego:
const { data, error } = games.insert([{
  mode,
  date: todayKey(),
  solution: mode === 'daily' ? dailyWord() : randomWord(),
  guesses: [],
  status: 'playing',
}]);

// Read con filtro (como .eq().eq())
const { data } = games.select({ mode: 'daily', date: todayKey() });
const existing = data && data.length ? data[data.length - 1] : null;
state.game = existing ?? startGame(mode);   // si no existe → CREATE

const guesses = [...state.game.guesses, guess];   // arreglo nuevo con el intento
let status = 'playing';
if (guess === state.game.solution) status = 'won';
else if (guesses.length === MAX_TRIES) status = 'lost';

const { data, error } = games.update(state.game.id, { guesses, status });

if (error || data.length === 0) {   // 0 filas = no se actualizó nada
  showToast('No se pudo guardar el intento');
  return null;
}

