const { data, error } = await db
  .from('cliente_práctica')
  .update(cambios)
  .eq('id', id)
  .select();

if (data.length === 0) {   // el RLS no dejó: no hay error, pero 0 filas
  console.log('No se actualizó ninguna fila...');
  return null;
}

