if (!btn.classList.contains('confirm')) {
  btn.classList.add('confirm');
  btn.textContent = '¿Seguro?';
  return;
}
const { data, error } = games.delete(btn.dataset.delete);

como_pasarlo_a_supabase.paso:
create table partidas (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid references auth.users(id) default auth.uid(),
  mode       text not null,
  date       date not null,
  solution   text not null,
  guesses    text[] not null default '{}',
  status     text not null default 'playing',
  created_at timestamptz default now()
);
alter table partidas enable row level security;
create policy "cada quien sus partidas" on partidas
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

// CREATE
await db.from('partidas').insert([{ mode, date, solution, guesses: [], status: 'playing' }]).select();
// READ
await db.from('partidas').select('*').eq('mode', 'daily').eq('date', today).maybeSingle();
// UPDATE
await db.from('partidas').update({ guesses, status }).eq('id', id).select();
// DELETE
await db.from('partidas').delete().eq('id', id).select();
